"""
Filename Sanitizer and Cleaner for Stock Assets.
Strips timestamps, resolution tags (2k, 4k, etc.), 'upscaled' tags,
and random generator artifacts, creating clean, professional, SEO-friendly filenames.
"""

from __future__ import annotations

import re
import unicodedata
from pathlib import Path


class FilenameCleaner:
    """Cleans and standardizes raw filenames generated by AI engines."""

    TIMESTAMP_PATTERNS = [
        # YYYYMMDD_HHMMSS or YYYYMMDD-HHMMSS or YYYYMMDD_HHMM
        r"[_ -]?\d{8}[_ -T]?\d{4,6}[_ -]?",
        # YYYY-MM-DD_HH-MM-SS or YYYY-MM-DD
        r"[_ -]?\d{4}[-_]\d{2}[-_]\d{2}(?:[-_T ]\d{2}[-_]\d{2}[-_]\d{2})?[_ -]?",
        # UNIX epoch timestamps (10 to 13 digits)
        r"[_ -]?[12]\d{9,12}[_ -]?",
        # Pure 8-digit date like 20261026
        r"[_ -]?20\d{6}[_ -]?",
    ]

    TAG_PATTERNS = [
        r"(?i)[-_ ]*(2k|4k|8k|1080p|720p|uhd|fhd|hd)[-_ ]*",
        r"(?i)[-_ ]*(upscaled|upscayl|high_fidelity|realesrgan)[-_ ]*",
        r"(?i)[-_ ]*(raw|generated|imgflow|imageflow)[-_ ]*",
    ]

    HASH_PATTERN = r"(?i)[-_ ]+[a-f0-9]{6,16}(?=[_ -]|$)"

    @classmethod
    def clean(cls, filename: str, fallback_slug: str | None = None) -> str:
        """
        Cleans a filename string (including or excluding extension).
        Example:
            'ImageFlow_20261026_153012_2k_business_meeting_a1b2c3d4.jpg'
            -> 'business_meeting.jpg'
        """
        path = Path(filename)
        ext = path.suffix.lower()
        stem = path.stem

        # 1. Normalize unicode
        stem = unicodedata.normalize("NFKD", stem).encode("ascii", "ignore").decode("ascii")

        # 2. Remove resolution & generator tags first
        for pattern in cls.TAG_PATTERNS:
            stem = re.sub(pattern, "_", stem)

        # 3. Remove timestamps
        for pattern in cls.TIMESTAMP_PATTERNS:
            stem = re.sub(pattern, "_", stem)

        # 4. Remove trailing or embedded hex hashes
        stem = re.sub(cls.HASH_PATTERN, "", stem)

        # 5. Clean punctuation and separators
        stem = re.sub(r"[^\w\s-]", "", stem)          # remove special characters
        stem = re.sub(r"[\s_-]+", "_", stem).strip("_") # collapse underscores/spaces

        # 6. Fallback if the name was completely stripped (e.g. was only date and resolution)
        if not stem or len(stem) < 3:
            if fallback_slug:
                stem = cls.slugify(fallback_slug)
            else:
                stem = "stock_asset"

        # Truncate if excessively long
        if len(stem) > 60:
            stem = stem[:60].rstrip("_")

        return f"{stem}{ext}" if ext else stem

    @classmethod
    def sanitize_file(cls, file_path: Path, fallback_slug: str | None = None) -> Path:
        """
        Renames the file on disk to its cleaned version.
        If a file with the target name already exists, appends _01, _02, etc.
        """
        if not file_path.exists():
            return file_path

        clean_name = cls.clean(file_path.name, fallback_slug=fallback_slug)
        target_path = file_path.parent / clean_name

        if target_path == file_path:
            return file_path

        idx = 1
        base_stem = target_path.stem
        ext = target_path.suffix
        while target_path.exists():
            target_path = file_path.parent / f"{base_stem}_{idx:02d}{ext}"
            idx += 1

        file_path.rename(target_path)
        return target_path

    @classmethod
    def slugify(cls, text: str) -> str:
        """Converts arbitrary text into a clean snake_case slug."""
        text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
        text = re.sub(r"[^\w\s-]", "", text.lower())
        return re.sub(r"[\s_-]+", "_", text).strip("_")[:50]
